/* 
 * NOTE: This program must typically be run as root to successfully call stime(2),
 * otherwise it will fail with EPERM.
 */
#define _DEFAULT_SOURCE
#include <time.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <unistd.h>

int main() {
    time_t current_time = time(NULL);
    // Calculate a target time 5 minutes (300 seconds) in the future
    time_t target_time = current_time + 300;

    printf("Current time (Epoch seconds): %ld\n", (long)current_time);
    printf("Target time to set: %ld\n", (long)target_time);

    if (stime(&target_time) == 0) {
        printf("Success: System time was set.\n");
    } else {
        perror("Error calling stime");
        if (errno == EPERM) {
            fprintf(stderr, "\nError: Permission denied. stime() requires superuser privileges (CAP_SYS_TIME).\n");
        } else {
             fprintf(stderr, "\nError code: %d\n", errno);
        }
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
